const input = $input.first().json;
const body = input.request?.body || {};

const sensitiveKeyPattern = /scanner\s*key|scanner_key|upload\s*token|upload_token|\bnonce\b|raw\s*hwid|machineguid|machine_guid|hardware\s*serial|\bserial\b|password|passwd|cookie|clipboard|screenshot|secret|authorization|bearer/i;
const privatePathPattern = /([A-Za-z]:\\Users\\)([^\\\s]+)(\\?)/g;
const unixPrivatePathPattern = /(\/Users\/)([^\/\s]+)(\/?)/g;

function truncate(value, max = 300) {
  if (value === undefined || value === null) return null;
  return String(value).slice(0, max);
}

function maskString(value) {
  return truncate(value, 500)
    .replace(privatePathPattern, '$1***$3')
    .replace(unixPrivatePathPattern, '$1***$3');
}

function sanitize(value, depth = 0) {
  if (depth > 3) return '[truncated]';
  if (value === undefined || value === null) return null;
  if (typeof value === 'string') return maskString(value);
  if (typeof value === 'number' || typeof value === 'boolean') return value;
  if (Array.isArray(value)) return value.slice(0, 10).map((item) => sanitize(item, depth + 1));
  if (typeof value === 'object') {
    const output = {};
    for (const [key, child] of Object.entries(value).slice(0, 25)) {
      if (sensitiveKeyPattern.test(String(key))) {
        output[key] = '[redacted]';
      } else {
        output[key] = sanitize(child, depth + 1);
      }
    }
    return output;
  }
  return truncate(value);
}

const severity = String(body.severity || 'INFO').toUpperCase();
const alert = {
  event: 'security.alert',
  severity,
  service: truncate(body.service || 'siderascan', 80),
  eventType: truncate(body.eventType || body.type || 'SECURITY_EVENT', 120),
  message: maskString(body.message || 'Security alert received.'),
  dashboardUrl: truncate(body.dashboardUrl || '', 500),
  createdAt: truncate(body.createdAt || new Date().toISOString(), 80),
  idempotencyKey: truncate(input.request?.idempotencyKey || '', 160),
  metadata: sanitize(body.metadata || {})
};

return [{ json: { alert } }];

