const input = $input.first().json;
const alert = input.alert;
const severity = String(alert?.severity || 'INFO').toUpperCase();
const discordEnabled = String(readEnv('DISCORD_SECURITY_ALERT_WEBHOOK_ENABLED', 'false')).toLowerCase() === 'true';
const discordUrl = readEnv('DISCORD_SECURITY_ALERT_WEBHOOK_URL');
const discordConfigured = /^https:\/\/discord(?:app)?\.com\/api\/webhooks\//i.test(discordUrl);
const shouldSend = discordEnabled && discordConfigured && ['HIGH', 'CRITICAL'].includes(severity);

if (!shouldSend) {
  return [];
}

