const alert = $input.first().json.alert;
const severity = String(alert.severity || 'INFO').toUpperCase();
const colorBySeverity = {
  CRITICAL: 12458077,
  HIGH: 16744192
};

function field(name, value, inline = true) {
  return {
    name,
    value: String(value || 'Unknown').slice(0, 1024),
    inline
  };
}

const metadataSummary = JSON.stringify(alert.metadata || {}, null, 2).slice(0, 900);
const description = String(alert.message || 'Security alert received.').slice(0, 1800);
const title = '[' + severity + '] ' + String(alert.eventType || 'Security alert').slice(0, 180);
const embed = {
  title,
  description,
  color: colorBySeverity[severity] || 16753920,
  fields: [
    field('Service', alert.service),
    field('Event Type', alert.eventType),
    field('Created At', alert.createdAt),
    field('Idempotency', alert.idempotencyKey, false),
    field('Metadata', metadataSummary ? '```json\n' + metadataSummary + '\n```' : 'No metadata.', false)
  ],
  footer: {
    text: 'SideraScan Security Alert'
  },
  timestamp: new Date(alert.createdAt || Date.now()).toISOString()
};

if (alert.dashboardUrl && /^https?:\/\//i.test(alert.dashboardUrl)) {
  embed.url = alert.dashboardUrl;
}

return [{
  json: {
    discordPayload: {
      username: 'SideraScan Alerts',
      embeds: [embed]
    }
  }
}];

