  return fallback;
}

const https = require('https');
const input = $input.first().json;
const webhookUrl = String(readEnv('DISCORD_SECURITY_ALERT_WEBHOOK_URL') || '').trim();

function assertDiscordWebhookURL(value) {
  const lower = String(value || '').toLowerCase();
  const ok = lower.startsWith('https://discord.com/api/webhooks/') || lower.startsWith('https://discordapp.com/api/webhooks/');
  if (!ok) throw new Error('Discord security alert webhook URL is not configured.');
  return value;
}

function postJSON(url, payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const request = https.request(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      },
      timeout: 30000
    }, (response) => {
      response.resume();
      response.on('end', () => resolve(response.statusCode || 0));
    });
    request.on('timeout', () => request.destroy(new Error('Discord alert delivery timed out.')));
    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

const statusCode = await postJSON(assertDiscordWebhookURL(webhookUrl), input.discordPayload);
if (statusCode < 200 || statusCode >= 300) {
  throw new Error('Discord alert delivery failed with HTTP ' + statusCode);
}

return [{ json: { discordSent: true, statusCode } }];
